return {["sort"]=0,["roomList"]={{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb42_02]],["connectPoint"]=0,["name"]=[[后山]],["permission"]=1,["enterable"]=1,["dsc"]=[[伏龙山虽位于江南之地，但毫无江南秀气，周围山林皆高耸入云，巍峨壮观。唯这里因为多年前的一场大火被烧得只剩下些许枯木，也因此走兽甚少，蛇虫却多。]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[后山(fb42_01)]],["canLeave"]=1,["id"]=[[fb42_01]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb42_03]],["connectPoint"]=0,["name"]=[[铁索桥]],["permission"]=1,["left"]=[[fb42_01]],["enterable"]=1,["dsc"]=[[用铁锁搭建而成的木桥。伏龙山因像巨龙赴海而得名，山上有八种天然奇观，地势起伏落差巨大，为了方便山中弟子行走，山与山之间用此铁索桥勾连。]],["down"]=[[fb42_06]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[铁索桥(fb42_02)]],["canLeave"]=1,["id"]=[[fb42_02]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[后山]],["permission"]=1,["left"]=[[fb42_02]],["enterable"]=1,["dsc"]=[[伏龙山虽位于江南之地，但毫无江南秀气，周围山林皆高耸入云，巍峨壮观。唯这里因为多年前的一场大火被烧得只剩下些许枯木，也因此走兽甚少，蛇虫却多。]],["fullName"]=[[后山(fb42_03)]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc53k]],["canLeave"]=1,["id"]=[[fb42_03]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[戏台]],["permission"]=1,["enterable"]=1,["dsc"]=[[戏台前是特意开辟的水塘，两侧有长廊相连，戏台周围又用玉石栏杆做隔绝，使得台上每一角皆成一景。距离戏台不远处又设长亭雅座，专门用来招待来客，角落里的小屋则方便唱戏之人上妆更衣。]],["down"]=[[fb42_08]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[戏台(fb42_04)]],["canLeave"]=1,["id"]=[[fb42_04]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb42_06]],["connectPoint"]=0,["name"]=[[走廊]],["permission"]=1,["enterable"]=1,["dsc"]=[[漏窗走廊，每每间隔数米则开辟一处漏窗，漏窗外遍植翠竹。一侧廊上又挂有竹帘和竹筒，竹筒成排，因是江湖帮派，少不了恩怨，若有外敌闯入时弟子会就近敲响竹筒传信。]],["down"]=[[fb42_10]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[走廊(fb42_05)]],["canLeave"]=1,["id"]=[[fb42_05]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb42_07]],["connectPoint"]=0,["name"]=[[小门]],["permission"]=1,["left"]=[[fb42_05]],["enterable"]=1,["up"]=[[fb42_02]],["dsc"]=[[通往后山的小门， 平日里并无弟子把守，因伏龙山山势险要，到此的人也很少。]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[小门(fb42_06)]],["canLeave"]=1,["id"]=[[fb42_06]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[杂物房]],["permission"]=1,["left"]=[[fb42_06]],["enterable"]=1,["dsc"]=[[堆放杂物的地方，有不少废弃的兵刃和木桩，常常会窜出几只老鼠，从杂物房的小窗向外看去是一片无底的悬崖，抬头则可见勾连伏龙山的铁索桥。]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[杂物房(fb42_07)]],["canLeave"]=1,["id"]=[[fb42_07]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb42_09]],["connectPoint"]=0,["name"]=[[后院]],["permission"]=1,["enterable"]=1,["up"]=[[fb42_04]],["dsc"]=[[有些杂乱的后院，放置着几口巨大的水缸，水缸上的木盖用石头压住，几个水桶挂在一边。地上全是带有泥土的脚印，角落的小门停着一辆推车。]],["fullName"]=[[后院(fb42_08)]],["visible"]=1,["dirIndex"]=0,["unit3"]=[[npc52p]],["unit2"]=[[npc52o]],["unit1"]=[[npc52n]],["canLeave"]=1,["id"]=[[fb42_08]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[回廊]],["permission"]=1,["left"]=[[fb42_08]],["enterable"]=1,["dsc"]=[[木石回廊，木制的回廊顶架，数根粗壮的梁柱支撑，但因下端临水，又用巨石作基座，廊外小池中还有多个木桩，几个空酒壶附在池水边缘。]],["down"]=[[fb42_15]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[回廊(fb42_09)]],["canLeave"]=1,["id"]=[[fb42_09]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb42_11]],["connectPoint"]=0,["name"]=[[走廊]],["permission"]=1,["enterable"]=1,["up"]=[[fb42_05]],["dsc"]=[[漏窗走廊，每每间隔数米则开辟一处漏窗，漏窗外遍植翠竹。一侧廊上又挂有竹帘和竹筒，竹筒成排，因是江湖帮派，少不了恩怨，若有外敌闯入时弟子会就近敲响竹筒传信。]],["down"]=[[fb42_16]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[走廊(fb42_10)]],["canLeave"]=1,["id"]=[[fb42_10]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb42_12]],["connectPoint"]=0,["name"]=[[走廊]],["permission"]=1,["left"]=[[fb42_10]],["enterable"]=1,["dsc"]=[[漏窗走廊，每每间隔数米则开辟一处漏窗，漏窗外遍植翠竹。一侧廊上又挂有竹帘和竹筒，竹筒成排，因是江湖帮派，少不了恩怨，若有外敌闯入时弟子会就近敲响竹筒传信。]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[走廊(fb42_11)]],["canLeave"]=1,["id"]=[[fb42_11]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb42_13]],["connectPoint"]=0,["name"]=[[假山]],["permission"]=1,["left"]=[[fb42_11]],["enterable"]=1,["dsc"]=[[不似江南瘦石，假山怪石嶙峋，毫无半点美感，似乎只是为了隔断而放置于此处。且假山内洞穴低矮，根本无法容身，更别说放置石椅作装饰，只能随意摆上几盆花卉遮掩洞口的杂乱。]],["fullName"]=[[假山(fb42_12)]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc53i]],["canLeave"]=1,["id"]=[[fb42_12]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[书房]],["permission"]=1,["left"]=[[fb42_12]],["enterable"]=1,["dsc"]=[[两层高的书房，分隔成两进，第一进是数排书架，分类详细，从儒家经典至武学秘籍，摆放整齐，书架顶端则有一金盆。第二进是一张案桌和成堆的账本，账目写有自伏龙山创立之初至今的明细。最右侧的墙壁上还挂有一把长剑，上面灰尘满满。]],["fullName"]=[[书房(fb42_13)]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc53l]],["canLeave"]=1,["id"]=[[fb42_13]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb42_15]],["connectPoint"]=0,["name"]=[[假山]],["permission"]=1,["enterable"]=1,["dsc"]=[[不似江南瘦石，假山怪石嶙峋，毫无半点美感，似乎只是为了隔断而放置于此处。且假山内洞穴低矮，根本无法容身，更别说放置石椅作装饰，只能随意摆上几盆花卉遮掩洞口的杂乱。]],["fullName"]=[[假山(fb42_14)]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc53j]],["canLeave"]=1,["id"]=[[fb42_14]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb42_16]],["connectPoint"]=0,["name"]=[[后花园]],["permission"]=1,["left"]=[[fb42_14]],["enterable"]=1,["up"]=[[fb42_09]],["dsc"]=[[后花园内摆放着两排兵器架，常有弟子在此练武，且附近多植松柏，并无盆景花卉。]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[后花园(fb42_15)]],["canLeave"]=1,["id"]=[[fb42_15]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb42_17]],["connectPoint"]=0,["name"]=[[走廊]],["permission"]=1,["left"]=[[fb42_15]],["enterable"]=1,["up"]=[[fb42_10]],["dsc"]=[[漏窗走廊，每每间隔数米则开辟一处漏窗，漏窗外遍植翠竹。一侧廊上又挂有竹帘和竹筒，竹筒成排，因是江湖帮派，少不了恩怨，若有外敌闯入时弟子会就近敲响竹筒传信。]],["down"]=[[fb42_21]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[走廊(fb42_16)]],["canLeave"]=1,["id"]=[[fb42_16]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb42_18]],["connectPoint"]=0,["name"]=[[花圃]],["permission"]=1,["left"]=[[fb42_16]],["enterable"]=1,["dsc"]=[[多排木架搭成的花圃，但因无人擅理，所以原本的花卉都干枯而死，许多杂草藤蔓反倒愈发富有生机，使得周围一派绿意。]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[花圃(fb42_17)]],["canLeave"]=1,["id"]=[[fb42_17]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb42_19]],["connectPoint"]=0,["name"]=[[小院]],["permission"]=1,["left"]=[[fb42_17]],["enterable"]=1,["dsc"]=[[四四方方的小院子，除了一个巨大的木桩和小池塘外再无其他。]],["fullName"]=[[小院(fb42_18)]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc53n]],["canLeave"]=1,["id"]=[[fb42_18]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[卧房]],["permission"]=1,["left"]=[[fb42_18]],["enterable"]=1,["dsc"]=[[简单而朴素的卧房，若非因为里头的书案上放有不少写有“任帮主亲启”的信件，定会认为这是普通弟子的卧房。房内左右两面分别悬挂弓箭、刀斧，正中两张原木椅披有虎皮，后以竹制屏风作隔挡，起居床榻一应俱全。]],["fullName"]=[[卧房(fb42_19)]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc53m]],["canLeave"]=1,["id"]=[[fb42_19]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb42_21]],["connectPoint"]=0,["name"]=[[瓜架]],["permission"]=1,["enterable"]=1,["dsc"]=[[乘凉的瓜架，木架上爬满了藤蔓，还开着许多黄白色的小花。四周放着两张石木桌，供给帮中弟子休息之用。]],["fullName"]=[[瓜架(fb42_20)]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc53h]],["canLeave"]=1,["id"]=[[fb42_20]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[后堂]],["permission"]=1,["left"]=[[fb42_20]],["fullName"]=[[后堂(fb42_21)]],["enterable"]=1,["up"]=[[fb42_16]],["dsc"]=[[伏龙堂后堂，前后门大敞，直通伏龙堂与走廊。堂内两侧放两张八角桌椅，可同时坐下数人。]],["down"]=[[fb42_23]],["visible"]=1,["dirIndex"]=0,["unit2"]=[[npc53o]],["unit1"]=[[npc50c]],["canLeave"]=1,["id"]=[[fb42_21]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb42_23]],["connectPoint"]=0,["name"]=[[侧厅]],["permission"]=1,["enterable"]=1,["dsc"]=[[伏龙堂侧厅，厅内三壁放有武器架，中间一个巨大铁炉，炉中烧有铁砂。几张座椅随意摆放，除此外再无其他。]],["fullName"]=[[侧厅(fb42_22)]],["visible"]=1,["dirIndex"]=0,["unit2"]=[[npc52h]],["unit1"]=[[npc52g]],["canLeave"]=1,["id"]=[[fb42_22]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb42_24]],["connectPoint"]=0,["name"]=[[伏龙堂]],["permission"]=1,["left"]=[[fb42_22]],["enterable"]=1,["up"]=[[fb42_21]],["dsc"]=[[伏龙堂为伏龙山议事、待客之地。堂内两侧房梁悬挂着灯油碟，一起点燃时可将堂内照的明亮无比。正中摆放巨石屏风作隔，屏风上又挂有两把刀斧，前放虎皮座椅，十分庄严。]],["down"]=[[fb42_26]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[伏龙堂(fb42_23)]],["canLeave"]=1,["id"]=[[fb42_23]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[侧厅]],["permission"]=1,["left"]=[[fb42_23]],["enterable"]=1,["dsc"]=[[伏龙堂侧厅，厅内三壁放有武器架，中间一个巨大铁炉，炉中烧有铁砂。几张座椅随意摆放，除此外再无其他。]],["fullName"]=[[侧厅(fb42_24)]],["visible"]=1,["dirIndex"]=0,["unit3"]=[[npc52k]],["unit2"]=[[npc52j]],["unit1"]=[[npc52i]],["canLeave"]=1,["id"]=[[fb42_24]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb42_26]],["connectPoint"]=0,["name"]=[[花圃]],["permission"]=1,["left"]=[[fb42_44]],["enterable"]=1,["dsc"]=[[多排木架搭成的花圃，但因无人擅理，所以原本的花卉都干枯而死，许多杂草藤蔓反倒愈发富有生机，使得周围一派绿意。]],["fullName"]=[[花圃(fb42_25)]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc52f]],["canLeave"]=1,["id"]=[[fb42_25]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb42_27]],["connectPoint"]=0,["name"]=[[广场]],["permission"]=1,["left"]=[[fb42_25]],["fullName"]=[[广场(fb42_26)]],["enterable"]=1,["up"]=[[fb42_23]],["dsc"]=[[四四方方的广场，四个角落都放有一只大旗，上写“威震江南”、“扬威天下”。顺着中央的石阶而上是一个演武台，弟子们常会在此处练功。]],["down"]=[[fb42_29]],["visible"]=1,["dirIndex"]=0,["unit2"]=[[npc53b]],["unit1"]=[[npc53a]],["canLeave"]=1,["id"]=[[fb42_26]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb42_28]],["connectPoint"]=0,["name"]=[[瓜架]],["permission"]=1,["left"]=[[fb42_26]],["enterable"]=1,["dsc"]=[[乘凉的瓜架，木架上爬满了藤蔓，还开着许多黄白色的小花。四周放着两张石木桌，供给帮中弟子休息之用。]],["fullName"]=[[瓜架(fb42_27)]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc53g]],["canLeave"]=1,["id"]=[[fb42_27]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[练功房]],["permission"]=1,["left"]=[[fb42_27]],["enterable"]=1,["dsc"]=[[伏龙山弟子们的练功房，房内十八般武器俱全，分隔数十间，每间可容下二人切磋。]],["fullName"]=[[练功房(fb42_28)]],["visible"]=1,["dirIndex"]=0,["unit2"]=[[npc52e]],["unit1"]=[[npc52d]],["canLeave"]=1,["id"]=[[fb42_28]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[山路]],["permission"]=1,["enterable"]=0,["up"]=[[fb42_26]],["dsc"]=[[伏龙山山路，以碎石铺路，层层石阶曲折迂回。路两侧黄土累累杂草丛生，平日里偶有鸟兽踪迹，却少有人烟。]],["down"]=[[fb42_31]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[山路(fb42_29)]],["canLeave"]=1,["id"]=[[fb42_29]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[客店雅间]],["permission"]=1,["fullName"]=[[客店雅间(fb42_30)]],["enterable"]=1,["dsc"]=[[虽说是客店的雅间，但其实十分简陋，屋内木床一张，破旧纱帐一顶；再有矮桌、木椅，皆有些年头了，一走进来便能闻见一股难以言喻的味道。]],["down"]=[[fb42_32]],["visible"]=1,["dirIndex"]=0,["unit2"]=[[npc53f]],["unit1"]=[[npc53e]],["canLeave"]=1,["id"]=[[fb42_30]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[山门]],["permission"]=1,["fullName"]=[[山门(fb42_31)]],["enterable"]=1,["up"]=[[fb42_29]],["dsc"]=[[伏龙山的山门，常有弟子在此把守，拦截误闯之人、接引山中来客。一侧还立有一块巨石，上写：伏龙山地界，擅闯者格杀勿论。]],["down"]=[[fb42_34]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc52m]],["canLeave"]=1,["id"]=[[fb42_31]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb42_33]],["connectPoint"]=0,["name"]=[[客店]],["permission"]=1,["enterable"]=1,["up"]=[[fb42_30]],["dsc"]=[[位于伏龙山的客店，寻常时候生意清冷，顶多会有些伏龙山弟子到此喝酒吃肉。店内一侧悬挂腊肉，旁边还放有一个木盆，里面装着几条鲜鱼。]],["fullName"]=[[客店(fb42_32)]],["visible"]=1,["leftDown"]=[[fb42_35]],["dirIndex"]=0,["unit3"]=[[npc52c]],["unit2"]=[[npc52b]],["unit1"]=[[npc52a]],["canLeave"]=1,["id"]=[[fb42_32]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[后院]],["permission"]=1,["left"]=[[fb42_32]],["enterable"]=1,["dsc"]=[[院内路道两侧有用篱笆作阻隔，篱笆内植有花草，还散落着一些大大小小的石头，看上去没有多少美感，似乎只是为了不让此地空旷而随意填塞。]],["fullName"]=[[后院(fb42_33)]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc53d]],["canLeave"]=1,["id"]=[[fb42_33]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb42_35]],["connectPoint"]=0,["name"]=[[山脚]],["permission"]=1,["enterable"]=1,["up"]=[[fb42_31]],["dsc"]=[[伏龙山山脚，附近只有一条山路可上山，细扫四周，只有几颗细长的小树，还有一口干涸了的枯井。]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[山脚(fb42_34)]],["canLeave"]=1,["id"]=[[fb42_34]],["mapHide"]=0},{["operations"]={},["rightUp"]=[[fb42_32]],["right"]=[[fb42_36]],["connectPoint"]=0,["name"]=[[黄土路]],["permission"]=1,["left"]=[[fb42_34]],["fullName"]=[[黄土路(fb42_35)]],["enterable"]=1,["up"]=[[fb42_45]],["dsc"]=[[黄土飞扬的小路，地上被碾出了许多车轴印，常有许多过路人从此前往嘉兴。]],["down"]=[[fb42_39]],["visible"]=1,["dirIndex"]=0,["unit3"]=[[npc09b]],["unit2"]=[[npc09a]],["unit1"]=[[npc08a]],["canLeave"]=1,["id"]=[[fb42_35]],["stepMusic"]=[[jiaobu]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[嘉兴镇外]],["permission"]=1,["left"]=[[fb42_35]],["enterable"]=1,["dsc"]=[[嘉兴镇郊外，树林葱郁，有一条宽阔的道路直通前方。从此前往，不过数里地就可抵达镇中，十分便捷。]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[嘉兴镇外(fb42_36)]],["canLeave"]=1,["id"]=[[fb42_36]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb42_38]],["connectPoint"]=0,["name"]=[[水泊岸口]],["permission"]=1,["rightDown"]=[[fb42_41]],["fullName"]=[[水泊岸口(fb42_37)]],["enterable"]=1,["dsc"]=[[伏龙山水泊的岸口，常有船只在此停靠。岸口的木桥栈上立有一根长杆，杆上挂有灯笼，写“伏龙山”三字，为来往者指明地界。]],["down"]=[[fb42_40]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc43b]],["canLeave"]=1,["id"]=[[fb42_37]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb42_39]],["connectPoint"]=0,["name"]=[[铁索桥]],["permission"]=1,["left"]=[[fb42_37]],["enterable"]=1,["dsc"]=[[用铁锁搭建而成的木桥，伏龙山水泊河流湍急，寻常的木桥根本无法长久使用，所以为了方便山中弟子行走搭建了此桥。]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[铁索桥(fb42_38)]],["canLeave"]=1,["id"]=[[fb42_38]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[黄土路]],["permission"]=1,["left"]=[[fb42_38]],["enterable"]=1,["up"]=[[fb42_35]],["dsc"]=[[黄土飞扬的小路，地上被碾出了许多车轴印，常有许多过路人从此前往嘉兴。]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[黄土路(fb42_39)]],["canLeave"]=1,["id"]=[[fb42_39]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[伏龙水泊]],["permission"]=1,["enterable"]=1,["up"]=[[fb42_37]],["dsc"]